import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * 缩放/平移手势：图片与 PDF 共用一套。
 *
 * 手机上看图/看图纸，用户的第一反应是**双指捏合、拖动、双击**；原来两个查看器只有
 * 按钮式缩放，且缩放后无法平移（图片 `transform: scale()` 一把推到中心，四周内容看不到）。
 * 这里统一实现：
 *   - 双指捏合：以两指中点为锚点缩放（内容不会从手指下"跑掉"）；
 *   - 单指拖动：仅在放大后平移，并按内容/容器尺寸夹住边界，避免把内容拖出屏幕；
 *   - 双击/双触：在适应尺寸与放大之间切换；
 *   - 滚轮/触控板捏合（ctrl+wheel）：桌面端等价操作。
 *
 * 不接管的手势：
 *   - 未放大时的单指拖动（`panAtFit = false` 时留给调用方做左右滑动切换）；
 *   - 普通滚轮（不 preventDefault，PDF 侧要留给页面滚动）。
 */

export interface ZoomPanState {
  scale: number;
  x: number;
  y: number;
}

export interface ZoomPanOptions {
  min?: number;
  max?: number;
  /** 双击/双触放大到的倍率。 */
  toggleScale?: number;
  /** 未放大时是否允许单指拖动平移（默认 false：留给左右滑动切换）。 */
  panAtFit?: boolean;
  /** 普通滚轮是否缩放；false 时只在 ctrl/⌘ + 滚轮（触控板捏合）时缩放。 */
  wheelZoom?: boolean;
  onChange?(state: ZoomPanState): void;
}

interface Point {
  x: number;
  y: number;
}

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);

export function useZoomPan({
  min = 1,
  max = 6,
  toggleScale = 2,
  panAtFit = false,
  wheelZoom = true,
  onChange,
}: ZoomPanOptions = {}) {
  const [state, setState] = useState<ZoomPanState>({ scale: 1, x: 0, y: 0 });
  /** 手势进行中：调用方据此临时关掉 CSS 过渡，否则每帧都要补一次动画，捏合跟不上手。 */
  const [gesturing, setGesturing] = useState(false);
  const surfaceRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLElement | null>(null);
  const pointers = useRef(new Map<number, Point>());
  const gesture = useRef<
    | { kind: 'pan'; pointerId: number; start: Point; origin: ZoomPanState }
    | { kind: 'pinch'; distance: number; origin: ZoomPanState }
    | null
  >(null);
  const lastTap = useRef(0);
  const stateRef = useRef(state);
  stateRef.current = state;

  /** 内容尺寸取**布局尺寸**（offsetWidth/Height 不受 transform 影响），容器取可视尺寸。 */
  const limits = useCallback((scale: number) => {
    const surface = surfaceRef.current;
    const content = contentRef.current;
    if (!surface || !content) return { x: 0, y: 0 };
    const width = content.offsetWidth || surface.clientWidth;
    const height = content.offsetHeight || surface.clientHeight;
    return {
      x: Math.max(0, (width * scale - surface.clientWidth) / 2),
      y: Math.max(0, (height * scale - surface.clientHeight) / 2),
    };
  }, []);

  const apply = useCallback((next: ZoomPanState) => {
    const scale = clamp(next.scale, min, max);
    const limit = limits(scale);
    const value: ZoomPanState = { scale, x: clamp(next.x, -limit.x, limit.x), y: clamp(next.y, -limit.y, limit.y) };
    stateRef.current = value;
    setState(value);
    onChange?.(value);
  }, [limits, max, min, onChange]);

  const reset = useCallback(() => apply({ scale: 1, x: 0, y: 0 }), [apply]);

  /** 以某个屏幕点为锚点缩放；不传锚点时以容器中心为锚点。 */
  const zoomTo = useCallback((scale: number, anchor?: Point) => {
    const surface = surfaceRef.current;
    const current = stateRef.current;
    const target = clamp(scale, min, max);
    if (!surface) {
      apply({ ...current, scale: target });
      return;
    }
    const rect = surface.getBoundingClientRect();
    const point = anchor ?? { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
    const cx = point.x - rect.left - rect.width / 2;
    const cy = point.y - rect.top - rect.height / 2;
    const ratio = target / current.scale;
    apply({ scale: target, x: cx - (cx - current.x) * ratio, y: cy - (cy - current.y) * ratio });
  }, [apply, max, min]);

  const zoomBy = useCallback((factor: number, anchor?: Point) => zoomTo(stateRef.current.scale * factor, anchor), [zoomTo]);

  useEffect(() => {
    // 容器尺寸变化（旋转屏幕/改窗口）后重新夹一次，避免内容停在界外。
    const surface = surfaceRef.current;
    if (!surface || typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(() => apply(stateRef.current));
    observer.observe(surface);
    return () => observer.disconnect();
  }, [apply]);

  const pointOf = (event: React.PointerEvent): Point => ({ x: event.clientX, y: event.clientY });

  const onPointerDown = (event: React.PointerEvent) => {
    if (event.pointerType === 'mouse' && event.button !== 0) return;
    pointers.current.set(event.pointerId, pointOf(event));
    if (pointers.current.size === 2) {
      const [a, b] = [...pointers.current.values()];
      if (!a || !b) return;
      gesture.current = {
        kind: 'pinch',
        distance: Math.hypot(a.x - b.x, a.y - b.y) || 1,
        origin: stateRef.current,
      };
      setGesturing(true);
      (event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId);
      return;
    }
    if (pointers.current.size === 1) {
      const current = stateRef.current;
      if (current.scale > 1 || panAtFit) {
        gesture.current = { kind: 'pan', pointerId: event.pointerId, start: pointOf(event), origin: current };
        setGesturing(true);
        (event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId);
      } else {
        gesture.current = null;
        // 双触放大：两次轻触间隔 < 300ms。
        const now = Date.now();
        if (now - lastTap.current < 300) {
          zoomTo(current.scale > 1.05 ? 1 : toggleScale, pointOf(event));
          lastTap.current = 0;
        } else {
          lastTap.current = now;
        }
      }
    }
  };

  const onPointerMove = (event: React.PointerEvent) => {
    if (!pointers.current.has(event.pointerId)) return;
    pointers.current.set(event.pointerId, pointOf(event));
    const active = gesture.current;
    if (!active) return;
    if (active.kind === 'pinch') {
      if (pointers.current.size < 2) return;
      const [a, b] = [...pointers.current.values()];
      if (!a || !b) return;
      const distance = Math.hypot(a.x - b.x, a.y - b.y) || 1;
      const ratio = distance / active.distance;
      const target = clamp(active.origin.scale * ratio, min, max);
      const rect = surfaceRef.current?.getBoundingClientRect();
      const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
      if (!rect) return;
      const ratioToOrigin = target / active.origin.scale;
      const cx = mid.x - rect.left - rect.width / 2;
      const cy = mid.y - rect.top - rect.height / 2;
      apply({
        scale: target,
        x: cx - (cx - active.origin.x) * ratioToOrigin,
        y: cy - (cy - active.origin.y) * ratioToOrigin,
      });
      return;
    }
    const dx = event.clientX - active.start.x;
    const dy = event.clientY - active.start.y;
    apply({ scale: active.origin.scale, x: active.origin.x + dx, y: active.origin.y + dy });
  };

  const release = (event: React.PointerEvent) => {
    pointers.current.delete(event.pointerId);
    if (pointers.current.size < 2 && gesture.current?.kind === 'pinch') {
      // 双指抬起后若仍有一指按着，转为平移更自然；这里直接结束手势。
      gesture.current = null;
    }
    if (pointers.current.size === 0) {
      gesture.current = null;
      setGesturing(false);
    }
    (event.currentTarget as HTMLElement).releasePointerCapture?.(event.pointerId);
  };

  const onWheel = (event: React.WheelEvent) => {
    if (!wheelZoom && !event.ctrlKey) return;
    // 触控板捏合会以 ctrl+wheel 到达；普通滚轮在图片页也直接缩放（页面本身没得滚）。
    event.preventDefault();
    zoomBy(event.deltaY < 0 ? 1.12 : 1 / 1.12, { x: event.clientX, y: event.clientY });
  };

  return {
    scale: state.scale,
    x: state.x,
    y: state.y,
    gesturing,
    /** 0 位移时用纯 scale()，便于断言与避免无谓的合成层。 */
    transform: state.x === 0 && state.y === 0
      ? `scale(${state.scale})`
      : `translate3d(${state.x}px, ${state.y}px, 0) scale(${state.scale})`,
    surfaceRef,
    contentRef,
    reset,
    zoomTo,
    zoomBy,
    handlers: { onPointerDown, onPointerMove, onPointerUp: release, onPointerCancel: release, onWheel },
  };
}
