import { useCallback, useEffect, useRef, useState } from 'react';
import { ChevronLeft, ChevronRight, Download, Expand, Maximize2, RefreshCw, RotateCcw, ZoomIn, ZoomOut } from 'lucide-react';
import { useZoomPan } from '../../shared/zoomPan';

export interface ImageViewerProps {
  src: string;
  alt: string;
  /** 同一批（同类型）资料里的前后项：用工具条按钮或 ←/→ 翻阅，像翻相册一样。 */
  onPrev?(): void;
  onNext?(): void;
  hasPrev?: boolean;
  hasNext?: boolean;
  /** 前后两张的地址：进入即预加载，切换时几乎立即出现。 */
  prevSrc?: string;
  nextSrc?: string;
  /** 形如「3 / 6」，放在工具条上让人知道自己在整批里的位置。 */
  position?: string;
}

/**
 * 图片阅读器。
 *
 * 相比原来的"三个按钮 + CSS scale"：
 *   - **双指捏合 / 双击 / 滚轮**缩放，缩放后可以**单指拖动**看四周（原来放大后只能看中心）；
 *   - 捏合以两指中点为锚点，内容不会从手指下跑掉；平移按内容尺寸夹边界；
 *   - 「适应屏幕 ⇄ 实际大小」一键切换，看细节时不用连点四次放大；
 *   - 同一批资料用工具条或 ←/→ 翻阅，并预加载前后两张。
 *
 * 有意**不做**触摸左右滑动切换：真机上"双指捏合"和"单指横划"在抬手瞬间难以可靠区分
 * （实测合成触摸里第二个 pointer 的 isPrimary、指针计数都会骗人），一旦误判就是
 * "刚放大就跳到下一张、缩放被复位"。翻页交给按钮与键盘，手势只负责缩放/平移。
 */
export function ImageViewer({ src, alt, onPrev, onNext, hasPrev = false, hasNext = false, prevSrc, nextSrc, position }: ImageViewerProps) {
  const [status, setStatus] = useState<'loading' | 'ready' | 'failed'>('loading');
  const [attempt, setAttempt] = useState(0);
  const [actualSize, setActualSize] = useState(false);
  const [hintVisible, setHintVisible] = useState(true);
  /** 加载提示延迟 250ms 再出现：命中缓存的图片瞬间就好，别闪一下"图片加载中"。 */
  const [slowLoading, setSlowLoading] = useState(false);
  const imageRef = useRef<HTMLImageElement | null>(null);

  const zoom = useZoomPan({ min: 1, max: 6, toggleScale: 2.5 });
  const { surfaceRef, contentRef, handlers } = zoom;

  const dismissHint = useCallback(() => setHintVisible(false), []);

  /**
   * 图片挂载时主动查一次 `complete`。
   * 为什么必须查：命中缓存（我们还会预加载前后两张）的图片可能在 React 挂上 `onLoad` 之前
   * 就已经加载完成，浏览器**不会再补发 load 事件** → 状态永远停在 loading，
   * "图片加载中"就一直挂在那儿（线上反馈的问题）。挂载时查 complete 是这件事的标准做法。
   */
  const handleImageRef = useCallback((node: HTMLImageElement | null) => {
    imageRef.current = node;
    contentRef.current = node;
    if (!node) return;
    if (node.complete && node.naturalWidth > 0) setStatus('ready');
  }, [contentRef]);

  useEffect(() => {
    if (status !== 'loading') {
      setSlowLoading(false);
      return;
    }
    const timer = window.setTimeout(() => setSlowLoading(true), 250);
    return () => window.clearTimeout(timer);
  }, [status]);

  // 预加载前后两张：切换时几乎立即出现。
  useEffect(() => {
    for (const url of [prevSrc, nextSrc]) {
      if (!url) continue;
      const image = new Image();
      image.src = url;
    }
  }, [nextSrc, prevSrc]);

  // 方向键翻阅（输入框聚焦时不抢键）。
  useEffect(() => {
    if (!onPrev && !onNext) return;
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null;
      if (target && /^(input|textarea|select)$/i.test(target.tagName)) return;
      if (event.key === 'ArrowLeft' && onPrev && hasPrev) { event.preventDefault(); onPrev(); }
      if (event.key === 'ArrowRight' && onNext && hasNext) { event.preventDefault(); onNext(); }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [hasNext, hasPrev, onNext, onPrev]);

  // 切换资料时复位缩放与状态。
  // `zoom.reset` 每次渲染都是新引用（手势状态在它内部），用 ref 转一手，
  // 让这个复位只认 src：换图才复位，转屏/重渲染不会把用户的放大状态清掉。
  const resetZoomRef = useRef(zoom.reset);
  resetZoomRef.current = zoom.reset;
  useEffect(() => {
    setStatus('loading');
    setActualSize(false);
    resetZoomRef.current();
  }, [src]);

  const toggleActualSize = () => {
    const image = imageRef.current;
    if (actualSize) {
      zoom.reset();
      setActualSize(false);
      return;
    }
    // 1:1 显示原始像素；图片尚未完成布局时（naturalWidth/offsetWidth 取不到）退化为 2×。
    const ratio = image?.naturalWidth && image.offsetWidth ? image.naturalWidth / image.offsetWidth : 2;
    zoom.zoomTo(ratio);
    setActualSize(true);
    dismissHint();
  };

  return (
    <div className="image-viewer">
      {status === 'failed' ? (
        <div className="media-fallback" role="alert">
          <strong>图片加载失败</strong>
          <p>图片无法加载，请重试或下载原图。</p>
          <button type="button" onClick={() => { setStatus('loading'); setAttempt(value => value + 1); }}><RefreshCw />重试图片</button>
          <a href={src} download><Download />下载原图</a>
        </div>
      ) : (
        <>
          <div
            className={`media-frame${zoom.gesturing ? ' is-gesturing' : ''}`}
            data-scale={zoom.scale}
            ref={node => { surfaceRef.current = node; }}
            {...handlers}
            onDoubleClick={() => { zoom.zoomTo(zoom.scale > 1.05 ? 1 : 2.5); dismissHint(); }}
            onWheel={event => { dismissHint(); handlers.onWheel(event); }}
          >
            <img
              key={attempt}
              ref={handleImageRef}
              src={src}
              alt={alt}
              draggable={false}
              onLoad={() => setStatus('ready')}
              onError={() => setStatus('failed')}
              style={{ transform: zoom.transform }}
            />
            {status === 'loading' && slowLoading && <p className="viewer-loading" role="status">图片加载中</p>}
          </div>
          {hintVisible && (
            <p className="viewer-hint">双指缩放 · 双击放大 · 放大后拖动查看</p>
          )}
          <div className="viewer-tools" aria-label="图片查看工具">
            {onPrev && <button type="button" aria-label="上一张" disabled={!hasPrev} onClick={onPrev}><ChevronLeft /></button>}
            {onNext && <button type="button" aria-label="下一张" disabled={!hasNext} onClick={onNext}><ChevronRight /></button>}
            <button type="button" aria-label="缩小图片" onClick={() => { dismissHint(); zoom.zoomBy(1 / 1.25); }} disabled={zoom.scale <= 1.01}><ZoomOut /></button>
            <button type="button" aria-label="放大图片" onClick={() => { dismissHint(); zoom.zoomBy(1.25); }} disabled={zoom.scale >= 5.99}><ZoomIn /></button>
            <button type="button" aria-label={actualSize ? '适应屏幕' : '查看实际大小'} aria-pressed={actualSize} className={actualSize ? 'is-active' : undefined} onClick={toggleActualSize}>{actualSize ? <Maximize2 /> : <Expand />}</button>
            <button type="button" aria-label="复位图片" onClick={() => { setActualSize(false); zoom.reset(); }}><RotateCcw /></button>
            {position && <span className="viewer-position">{position}</span>}
          </div>
        </>
      )}
    </div>
  );
}

export default ImageViewer;
